using System;using System.Collections.Generic;using System.Globalization;using System.Linq;using UnityEngine;
namespace Staff.Traversal {
// The supplied study_tangent: Write, rigid stable symbols, contour transforms, Uncreate wrappers.
[DefaultExecutionOrder(200)] public sealed class TangentEquationUI:MonoBehaviour {
 public enum AnimationPhase{Hidden,Writing,Symbolic,Substituting,Numeric,Erasing}
 public AnimationPhase Phase{get;private set;}
 [Min(.05f)] public float creationSeconds=.65f,substitutionSeconds=.85f,disappearanceSeconds=.35f;
 public float Slope{get;private set;}public float Height{get;private set;}public float ContactX{get;private set;}public bool Vertical{get;private set;}
 public bool HasSubstitution=>Phase==AnimationPhase.Substituting||Phase==AnimationPhase.Numeric;
 public bool IsVisible=>Phase!=AnimationPhase.Hidden;
 public string EvaluatedFormula=>Vertical?"x="+Number(ContactX):"y="+Number(Slope)+"(x-"+Number(ContactX)+")"+(Height<=-.005f?"-":"+")+Number(Mathf.Abs(Height));
 TangentContourData data;readonly Dictionary<string,TangentGlyph> glyphs=new Dictionary<string,TangentGlyph>();TangentTraversal traversal;Camera cameraView;Canvas overlay;TangentContourGraphic graphic;Vector3 target;Vector2 screenPosition,size,lastPosition,lastSize;bool hasTarget;float clock;
 List<Atom>[] layouts;List<Blend>[] blends;List<TangentPlot> eraseSnapshot;
 sealed class Atom{public string key,id;public Vector2[][] paths;}
 sealed class Blend{public Vector2[][] from,to;public bool erase,birth;}
 void OnEnable(){Initialize(GetComponent<TangentTraversal>());Phase=AnimationPhase.Hidden;clock=0;}
 public void Initialize(TangentTraversal owner){traversal=owner;if(data!=null&&layouts!=null&&layouts[0]!=null&&glyphs.Count==data.glyphs.Length)return;var asset=Resources.Load<TextAsset>("TangentMath/contours");if(!asset){Debug.LogError("Missing Manim tangent contour export",this);return;}data=JsonUtility.FromJson<TangentContourData>(asset.text);foreach(var glyph in data.glyphs)glyphs[glyph.key]=glyph;layouts=new List<Atom>[4];layouts[0]=Layout(0);var source=GetComponent<Staff.MathSpace.LatexSymbol>();if(!source)source=gameObject.AddComponent<Staff.MathSpace.LatexSymbol>();source.SetSource(@"y=f'(a)(x-a)+f(a)",Resources.Load<Texture2D>("TangentMath/symbol/symbol"),"Assets/StaffTraversal/Tools/TangentStudioReference.py");}
 public void BeginAim(Camera camera,Vector2 reticle){Initialize(GetComponent<TangentTraversal>());cameraView=camera;screenPosition=reticle;hasTarget=false;clock=0;Phase=AnimationPhase.Writing;eraseSnapshot=null;size=new Vector2(180,30);}
 public void Measure(Vector3 source,Vector3 point){target=point;var d=point-source;ContactX=new Vector2(d.x,d.z).magnitude;Height=point.y;Vertical=ContactX<.001f;Slope=Vertical?0:Mathf.Tan(Mathf.Atan2(d.y,ContactX));}
 public void Lock(Vector3 source,Vector3 point){Measure(source,point);hasTarget=true;for(int i=0;i<4;i++)layouts[i]=Layout(i);blends=new List<Blend>[3];for(int i=0;i<3;i++)blends[i]=MakeBlend(layouts[i],layouts[i+1]);Phase=AnimationPhase.Substituting;clock=0;}
 public void Present(bool show,Camera camera,Vector3 source,Vector3 point){if(camera)cameraView=camera;if(Phase==AnimationPhase.Erasing||Phase==AnimationPhase.Hidden)return;if(show){target=point;hasTarget=true;}else if(traversal&&traversal.IsScreenAiming){hasTarget=false;screenPosition=traversal.AimScreenPosition;}else Dismiss();}
 public void Dismiss(){if(Phase==AnimationPhase.Hidden||Phase==AnimationPhase.Erasing)return;eraseSnapshot=Frame();Phase=AnimationPhase.Erasing;clock=0;}
 public void Advance(float dt){if(Phase==AnimationPhase.Hidden)return;clock+=Mathf.Max(0,dt);if(Phase==AnimationPhase.Writing&&clock>=creationSeconds){Phase=AnimationPhase.Symbolic;clock=0;}else if(Phase==AnimationPhase.Substituting&&clock>=substitutionSeconds){Phase=AnimationPhase.Numeric;clock=0;}else if(Phase==AnimationPhase.Erasing&&clock>=disappearanceSeconds){Phase=AnimationPhase.Hidden;clock=0;}}
 static string Number(float value)=>(Mathf.Abs(value)<.005f?0:value).ToString("0.00",CultureInfo.InvariantCulture);
 public static Vector2 DisplaySize(Camera camera,Vector3 point){float depth=Mathf.Max(.1f,Vector3.Dot(point-camera.transform.position,camera.transform.forward));float units=camera.orthographic?camera.orthographicSize*2/Mathf.Max(1,camera.pixelHeight):2*depth*Mathf.Tan(camera.fieldOfView*Mathf.Deg2Rad*.5f)/Mathf.Max(1,camera.pixelHeight);float h=Mathf.Clamp(.5f/units,30,60);h=Mathf.Min(h,Mathf.Max(1,(Screen.width-32)/6f));return new Vector2(h*6,h);}
 float Smooth(float t){return data.smooth[Mathf.Clamp(Mathf.RoundToInt(Mathf.Clamp01(t)*(data.smooth.Length-1)),0,data.smooth.Length-1)];}
 List<Atom> Layout(int stage){var specs=new List<(string key,string id,float gap)>();Action<string,string,int> add=(key,id,slot)=>specs.Add((key,id,data.slots[slot].gap));Action<string,string,int> number=(text,id,slot)=>{for(int i=0;i<text.Length;i++)specs.Add((text[i].ToString(),id,i==text.Length-1?data.slots[slot].gap:.035f));};
 if(Vertical&&stage==3){add("x","y",0);add("=","eq",1);number(Number(ContactX),"arg1",16);}else{
 add("y","y",0);add("=","eq",1);
 if(stage<3){add("f","sf",2);add("'","sp",3);add("(","so",4);if(stage==0)add("a","arg1",5);else number(Number(ContactX),"arg1",5);add(")","sc",6);}else number(Number(Slope),"arg1",6);
 add("(","left",7);add("x","x",8);add("-","minus",9);if(stage==0)add("a","arg2",10);else number(Number(ContactX),"arg2",10);add(")","right",11);add(stage>=2&&Height<=-.005f?"-":"+","sign",12);
 if(stage<2){add("f","hf",13);add("(","ho",14);if(stage==0)add("a","arg3",15);else number(Number(ContactX),"arg3",15);add(")","hc",16);}else number(Number(Mathf.Abs(Height)),"arg3",16);
 }
 float width=specs.Sum(s=>glyphs[s.key].width+s.gap);float pen=-width*.5f;var result=new List<Atom>();foreach(var spec in specs){var glyph=glyphs[spec.key];float center=pen+glyph.width*.5f;result.Add(new Atom{key=spec.key,id=spec.id,paths=glyph.contours.Select(c=>c.points.Select(p=>p+Vector2.right*center).ToArray()).ToArray()});pen+=glyph.width+spec.gap;}return result;
 }
 static float Area(Vector2[] path){float sum=0;for(int i=0;i<path.Length;i++){var a=path[i];var b=path[(i+1)%path.Length];sum+=a.x*b.y-a.y*b.x;}return sum*.5f;}
 static Vector2 Center(Vector2[] p){var sum=Vector2.zero;foreach(var v in p)sum+=v;return sum/p.Length;}
 static Vector2 Center(Vector2[][] p)=>Center(p.SelectMany(x=>x).ToArray());
 // Literal port of the reference's contour pairing: area, winding, arc-length phase alignment.
 static Blend Morph(Vector2[][] aa,Vector2[][] bb){aa=aa.OrderByDescending(p=>Mathf.Abs(Area(p))).ToArray();bb=bb.OrderByDescending(p=>Mathf.Abs(Area(p))).ToArray();if(Area(aa[0])*Area(bb[0])<0)bb=bb.Select(p=>p.Reverse().ToArray()).ToArray();var left=new List<Vector2[]>();var right=new List<Vector2[]>();int count=Mathf.Max(aa.Length,bb.Length);var ca=Center(aa);var cb=Center(bb);for(int k=0;k<count;k++){var a=k<aa.Length?aa[k]:Enumerable.Repeat(Center(bb[k])-cb+ca,128).ToArray();var b=k<bb.Length?bb[k]:Enumerable.Repeat(Center(aa[k])-ca+cb,128).ToArray();if(k<aa.Length&&k<bb.Length){var ac=Center(a);var bc=Center(b);int best=0;float error=float.PositiveInfinity;for(int shift=0;shift<128;shift++){float e=0;for(int i=0;i<128;i++)e+=((a[i]-ac)-(b[(i+shift)%128]-bc)).sqrMagnitude;if(e<error){error=e;best=shift;}}b=Enumerable.Range(0,128).Select(i=>b[(i+best)%128]).ToArray();}left.Add(a);right.Add(b);}return new Blend{from=left.ToArray(),to=right.ToArray()};}
 static List<Blend> MakeBlend(List<Atom> a,List<Atom> b){var result=new List<Blend>();foreach(var id in a.Select(x=>x.id).Concat(b.Select(x=>x.id)).Distinct()){var from=a.Where(x=>x.id==id).ToArray();var to=b.Where(x=>x.id==id).ToArray();var aa=from.SelectMany(x=>x.paths).ToArray();var bb=to.SelectMany(x=>x.paths).ToArray();if(to.Length==0)result.Add(new Blend{from=aa,to=aa,erase=true});else if(from.Length==0)result.Add(new Blend{from=bb,to=bb,birth=true});else if(from.Select(x=>x.key).SequenceEqual(to.Select(x=>x.key)))result.Add(new Blend{from=aa,to=bb});else result.Add(Morph(aa,bb));}return result;}
 List<TangentPlot> Frame(){var plots=new List<TangentPlot>();if(data==null)return plots;if(Phase==AnimationPhase.Erasing){float coverage=1-Smooth(clock/disappearanceSeconds);foreach(var saved in eraseSnapshot)plots.Add(new TangentPlot(TangentContourGraphic.Partial(saved.paths,saved.coverage)){fill=saved.fill,stroke=saved.stroke,coverage=coverage});return plots;}
 if(Phase==AnimationPhase.Substituting){float t=Mathf.Clamp01(clock/substitutionSeconds);int index=t<2.8f/6.8f?0:t<4.8f/6.8f?1:2;float begin=index==0?0:index==1?2.8f/6.8f:4.8f/6.8f;float duration=index==0?2.8f/6.8f:2/6.8f;float local=Mathf.Clamp01((t-begin)/duration),smooth=Smooth(local);foreach(var blend in blends[index]){if(blend.erase){plots.Add(new TangentPlot(blend.from){coverage=1-Smooth(Mathf.Clamp01(local/.325f))});continue;}if(blend.birth){plots.Add(new TangentPlot(blend.to){coverage=smooth});continue;}var paths=new Vector2[blend.from.Length][];for(int k=0;k<paths.Length;k++){paths[k]=new Vector2[blend.from[k].Length];for(int j=0;j<paths[k].Length;j++)paths[k][j]=Vector2.Lerp(blend.from[k][j],blend.to[k][j],smooth);}plots.Add(new TangentPlot(paths));}return plots;}
 var layout=layouts[Phase==AnimationPhase.Numeric?3:0];for(int i=0;i<layout.Count;i++){var plot=new TangentPlot(layout[i].paths);if(Phase==AnimationPhase.Writing){var frame=data.writeFrames[Mathf.Clamp(Mathf.RoundToInt(clock/creationSeconds*(data.writeFrames.Length-1)),0,data.writeFrames.Length-1)].glyphs[i];plot.fill=frame.fill;plot.stroke=frame.stroke;plot.coverage=frame.coverage;}plots.Add(plot);}return plots;}
 void EnsureOverlay(){if(overlay)return;var root=new GameObject("UI - Tangent equation",typeof(RectTransform),typeof(Canvas));UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(root,gameObject.scene);overlay=root.GetComponent<Canvas>();overlay.renderMode=RenderMode.ScreenSpaceOverlay;overlay.sortingOrder=100;root.layer=5;var go=new GameObject("Manim contour equation",typeof(RectTransform),typeof(CanvasRenderer),typeof(TangentContourGraphic));go.layer=5;go.transform.SetParent(root.transform,false);graphic=go.GetComponent<TangentContourGraphic>();graphic.raycastTarget=false;graphic.color=Color.white;graphic.rectTransform.anchorMin=graphic.rectTransform.anchorMax=new Vector2(0,1);graphic.rectTransform.pivot=new Vector2(.5f,.5f);}
 void LateUpdate(){Render(Time.deltaTime);}
 public void Render(float dt){EnsureOverlay();Advance(dt);overlay.gameObject.SetActive(IsVisible);if(!IsVisible||!cameraView||data==null)return;graphic.color=TangentTraversal.InkColor(cameraView);var plots=Frame();if(Phase!=AnimationPhase.Erasing){if(hasTarget){var p=cameraView.WorldToScreenPoint(target);if(p.z>0)screenPosition=p;size=DisplaySize(cameraView,target);}else{if(traversal&&traversal.IsScreenAiming)screenPosition=traversal.AimScreenPosition;size=new Vector2(180,30);}lastSize=size;lastPosition=screenPosition;}else{size=lastSize;screenPosition=lastPosition;}
 float sx=size.x*.94f/data.width,sy=size.y*.61f/data.height;float extent=0;foreach(var p in plots)foreach(var path in p.paths)foreach(var v in path)extent=Mathf.Max(extent,Mathf.Abs(v.x)*sx);float cx=Mathf.Clamp(screenPosition.x,extent+16,Mathf.Max(extent+16,Screen.width-extent-16));float cy=Mathf.Clamp(Screen.height-screenPosition.y-size.y*1.4f,size.y*.5f+16,Mathf.Max(size.y*.5f+16,Screen.height-size.y*.5f-16));graphic.rectTransform.anchoredPosition=new Vector2(cx,-cy);graphic.rectTransform.sizeDelta=size;graphic.scale=new Vector2(sx,sy);graphic.baseline=data.bottom+data.height*.5f;graphic.plots=plots;graphic.SetVerticesDirty();}
 void OnDisable(){Phase=AnimationPhase.Hidden;if(overlay)overlay.gameObject.SetActive(false);}
 void OnDestroy(){if(overlay)Destroy(overlay.gameObject);}
}
}
